const createPipeline = () => {
  // Ingest: IoT Hub
  // Store: Delta Lake partitions per tenant on ADLS Gen2
  // Analyze: Synapse serverless
  // Train: Azure ML with registry
  // Govern: Purview + RBAC, BYOK, DR, cost controls
}
```

